import sys

MOD = 998244353


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    y = [n + 1] + [0] * n + [0]
    for k in range(n):
        x, v = data[1 + 2*k:3 + 2*k]
        y[x] = v

    dp = [0] * (n + 2)
    dp[0] = 1
    for b in range(1, n + 2):
        low = y[b]
        total = 0
        for a in range(b):
            high = y[a]
            if high <= low or dp[a] == 0:
                continue
            vals = [y[k] for k in range(a + 1, b) if low < y[k] < high]
            # An isolated point is both a prefix minimum and suffix maximum.
            pref = n + 2
            candidates = []
            for v in vals:
                candidates.append(v < pref)
                if v < pref:
                    pref = v
            right_max = 0
            valid = True
            for k in range(len(vals) - 1, -1, -1):
                v = vals[k]
                if candidates[k] and v > right_max:
                    valid = False
                    break
                if v > right_max:
                    right_max = v
            if valid:
                total += dp[a]
        dp[b] = total % MOD
    print(dp[n + 1])


if __name__ == '__main__':
    solve()

