import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]

    # bound[l][k]: minimum right endpoint of a condition with
    # forbidden maximum k and left endpoint at least l.
    bound = [[n + 1] * n for _ in range(n + 1)]
    for i in range(2, len(data), 3):
        l, r, x = data[i:i + 3]
        l -= 1
        x -= 1
        if r < bound[l][x]:
            bound[l][x] = r
    for l in range(n - 1, -1, -1):
        row = bound[l]
        nxt = bound[l + 1]
        for k in range(l, n):
            if nxt[k] < row[k]:
                row[k] = nxt[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][end] is the valid relative-order count on [l,end),
    # divided by (end-l)! modulo MOD.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for l in range(n, -1, -1):
        dp[l][l] = 1
        row = dp[l]
        limits = bound[l]
        for end in range(l + 1, n + 1):
            total = 0
            for k in range(l, end):
                if limits[k] > end:
                    total += row[k] * dp[k + 1][end]
            row[end] = total * inv[end - l] % MOD

    ans = dp[0][n]
    for i in range(1, n + 1):
        ans = ans * i % MOD
    print(ans)


if __name__ == '__main__':
    main()

