import sys
from collections import deque

MOD = 998244353


def solve(n, m, a):
    indeg = [0] * n
    for v in a:
        indeg[v] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    # dp[u][j] counts the attached tree when x[u] = j + 1.
    # None represents an array consisting entirely of ones.
    dp = [None] * n
    while q:
        u = q.popleft()
        v = a[u]
        child = dp[u]
        parent = dp[v]
        if child is None:
            if parent is None:
                parent = list(range(1, m + 1))
                dp[v] = parent
            else:
                for j in range(m):
                    parent[j] = parent[j] * (j + 1) % MOD
        else:
            total = 0
            if parent is None:
                for j in range(m):
                    total = (total + child[j]) % MOD
                    child[j] = total
                dp[v] = child
            else:
                for j in range(m):
                    total = (total + child[j]) % MOD
                    parent[j] = parent[j] * total % MOD
        dp[u] = None
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)

    ans = 1
    for start in range(n):
        if indeg[start] == 0:
            continue
        # Every value on a directed cycle must be equal.
        product = None
        u = start
        while indeg[u]:
            indeg[u] = 0
            values = dp[u]
            if values is not None:
                if product is None:
                    product = values
                else:
                    for j in range(m):
                        product[j] = product[j] * values[j] % MOD
            dp[u] = None
            u = a[u]
        ways = m if product is None else sum(product) % MOD
        ans = ans * ways % MOD
    return ans


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    print(solve(n, m, [v - 1 for v in data[2:]]))


if __name__ == '__main__':
    main()

