import sys
import math

MOD = 998244353


def compute(n, arr):
    events = {}
    for i, a in enumerate(arr, 1):
        p = 2
        while p * p <= a:
            if a % p == 0:
                e = 0
                while a % p == 0:
                    a //= p
                    e += 1
                events.setdefault(p, []).append((i, e))
            p += 1
        if a > 1:
            events.setdefault(a, []).append((i, 1))

    ans = 1
    for p, ev in events.items():
        g = 0
        for _, e in ev:
            g = math.gcd(g, e)
        base = pow(p, g, MOD)
        total = sum(e // g for _, e in ev)
        cache = {}
        dp = [1]

        for j, (i, e) in enumerate(ev):
            e //= g
            gap = (ev[j + 1][0] if j + 1 < len(ev) else n) - i
            weights = cache.get(gap)
            if weights is None:
                b = pow(base, gap, MOD)
                weights = [1] * (total + 1)
                for h in range(1, total + 1):
                    weights[h] = weights[h - 1] * b % MOD
                cache[gap] = weights

            q = pow(base, i, MOD)
            z = 0
            limit = min(e, len(dp))
            for h in range(limit):
                z = (z + dp[h]) * q % MOD
            z = z * pow(q, e - limit, MOD) % MOD

            size = len(dp) + e
            padded = [0] * e + dp + [0] * (2 * e)
            nd = [0] * size
            nd[0] = (z + padded[2 * e]) % MOD
            for h in range(1, size):
                nd[h] = (padded[h] + padded[h + 2 * e]) * weights[h] % MOD
            dp = nd

        ans = ans * (sum(dp) % MOD) % MOD
    return ans


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(compute(data[0], data[1:]))


