class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # depth[w] is the number of operations needed to reduce w to 1.
        depth = [0] * (length + 1)
        for w in range(2, length + 1):
            depth[w] = 1 + depth[w.bit_count()]

        # Counts for prefixes already strictly smaller than s's prefix.
        counts = [0] * (length + 1)
        tight_ones = 0
        for i, bit in enumerate(s):
            for w in range(i + 1, 0, -1):
                counts[w] = (counts[w] + counts[w - 1]) % mod
            if bit == '1':
                counts[tight_ones] = (counts[tight_ones] + 1) % mod
                tight_ones += 1

        return sum(
            counts[w] for w in range(1, length + 1) if depth[w] < k
        ) % mod

