import sys


def solve(a):
    best = 0
    stack = [(a, 0, 0, 0)]
    while stack:
        a, score, p0, p1 = stack.pop()
        if len(a) <= 1:
            best = max(best, score + max(p0, p1) + len(a))
            continue
        even = []
        odd = []
        e0 = e1 = o0 = o1 = 0
        for q in a:
            if q & 1:
                odd.append((q + 1) >> 1)
                if q & 2:
                    o0 += 1
                else:
                    o1 += 1
            else:
                even.append(q >> 1)
                if q & 2:
                    e0 += 1
                else:
                    e1 += 1
        stack.append((even, score + p0, o0, o1))
        stack.append((odd, score + p1, e0, e1))
    return best


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(solve(data[1:]))


