import sys

def solve(n, edges):
    rows = [0] * n
    for u, v in edges:
        rows[u] |= 1 << v
        rows[v] |= 1 << u
    pivots = []
    rank = 0
    for col in range(n):
        bit = 1 << col
        pivot = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if pivot == -1:
            continue
        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1
    pivot_set = set(pivots)
    free = [i for i in range(n) if i not in pivot_set]
    values = [0] * n
    for j, col in enumerate(free):
        values[col] = 1 << j
    for i, col in enumerate(pivots):
        for f in free:
            if rows[i] & (1 << f):
                values[col] ^= values[f]
    return values if all(values) else None

