from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        ans = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            tr, tc = dc, -dr
            suffix = [0] * (n * m)
            rows = range(n - 1, -1, -1) if tr == 1 else range(n)
            for r in rows:
                row = grid[r]
                base = r * m
                nr = r + tr
                for c in range(m):
                    v = row[c]
                    length = 1
                    nc = c + tc
                    if 0 <= nr < n and 0 <= nc < m:
                        if grid[nr][nc] == (2 if v == 1 else 2 - v):
                            length += suffix[nr * m + nc]
                    suffix[base + c] = length
            prev = [0] * m
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            for r in rows:
                cur = [0] * m
                base = r * m
                for c, v in enumerate(grid[r]):
                    length = 0
                    if v == 1:
                        length = 1
                    else:
                        pc = c - dc
                        if 0 <= pc < m:
                            p = prev[pc]
                            if p and v == (2 if p & 1 else 0):
                                length = p + 1
                    cur[c] = length
                    if length:
                        candidate = length + suffix[base + c] - 1
                        if candidate > ans:
                            ans = candidate
                prev = cur
        return ans

