class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        m = (n + 1) // 2
        weights = [(powers[i] + powers[n - 1 - i]) % k if i != n - 1 - i else powers[i] % k for i in range(m)]
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])
        result = []
        remainder = 0
        for i, w in enumerate(weights):
            for d in range(9, 0 if i == 0 else -1, -1):
                candidate = remainder + d * w
                if candidate % suffix[i + 1] == 0:
                    result.append(str(d))
                    remainder = candidate % k
                    break
        half = ''.join(result)
        return half + (half[:-1] if n % 2 else half)[::-1]

