        y = next(it) - 1
        z = next(it)
        graph[x].append((y, z))
        graph[y].append((x, z))
    values = [-1] * n
    for root in range(n):
        if values[root] != -1:
            continue
        values[root] = 0
        component = [root]
        used_bits = 0
        for v in component:
            dv = values[v]
            used_bits |= dv
            for w, z in graph[v]:
                want = dv ^ z
                if values[w] == -1:
                    values[w] = want
                    component.append(w)
