import sys
import heapq


def solve(N, W, items):
    groups = [[] for _ in range(W + 1)]
    for w, v in items:
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w, h in enumerate(groups):
        if not h:
            continue
        heapq.heapify(h)
        vals = []
        for _ in range(W // w):
            v = -h[0]
            if v <= 0:
                break
            vals.append(v)
            heapq.heapreplace(h, 2 - v)
        if not vals:
            continue

        if w >= 60 or len(vals) < 8:
            for v in vals:
                for j in range(W, w - 1, -1):
                    nv = dp[j - w] + v
                    if nv > dp[j]:
                        dp[j] = nv
        else:
            cum = [0]
            for v in vals:
                cum.append(cum[-1] + v)
            m = len(vals)
            ndp = [0] * (W + 1)
            for r in range(w):
                old = dp[r::w]
                L = len(old)

                def rec(lo, hi, a, b):
                    if lo > hi:
                        return
                    mid = (lo + hi) // 2
                    best = -1
                    opt = a
                    for t in range(max(a, mid - m), min(b, mid) + 1):
                        score = old[t] + cum[mid - t]
                        if score > best:
                            best = score
                            opt = t
                    ndp[r + mid * w] = best
                    rec(lo, mid - 1, a, opt)
                    rec(mid + 1, hi, opt, b)

                rec(0, L - 1, 0, L - 1)
            dp = ndp
    return dp[W]


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, W = data[:2]
    items = list(zip(data[2::2], data[3::2]))
    print(solve(N, W, items))


if __name__ == '__main__':
    main()

