from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            v = stack.pop()
            if v >= 0:
                start[v] = len(order)
                stack.append(~v)
                stack.extend(reversed(children[v]))
            else:
                v = ~v
                order.append(s[v])
                end[v] = len(order)

        t = '#' + '#'.join(order) + '#'
        m = len(t)
        radius = [0] * m
        center = right = 0
        for i in range(m):
            if i < right:
                radius[i] = min(right - i, radius[2 * center - i])
            r = radius[i]
            while i - r - 1 >= 0 and i + r + 1 < m and t[i - r - 1] == t[i + r + 1]:
                r += 1
            radius[i] = r
            if i + r > right:
                center, right = i, i + r
        return [radius[start[v] + end[v]] >= end[v] - start[v] for v in range(n)]

