import sys
import decimal

MOD = 998244353

def solve(n, s):
    if s[0] != 'B' or s[-1] != 'W':
        return 0
    bs = [0]
    b = 0
    for c in s:
        if c == 'B':
            b += 1
        else:
            bs.append(b)
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i % MOD
    inv = [1] * (n + 1)
    inv[n] = pow(fact[n], MOD-2, MOD)
    for i in range(n, 0, -1):
        inv[i-1] = inv[i] * i % MOD
    dp = fact.copy()
    a = [0] * (n + 1)
    ctx = decimal.getcontext()
    ctx.prec = 24 * (3*n + 10)
    ctx.Emax = 999999999
    ctx.Emin = -999999999
    fs = ''.join(f'{x:024d}' for x in reversed(fact))
    D = decimal.Decimal

    def rec(l, r):
        if r-l < 32:
            for w in range(l, r+1):
                b = bs[w]
                if b <= w:
                    total = dp[w]
                    for v in range(l, w):
                        if a[v]:
                            total -= a[v] * fact[w-bs[v]]
                    a[w] = total * inv[w-b] % MOD
            return
        m = (l+r)//2
        rec(l, m)
        groups = {}
        for v in range(l, m+1):
            if a[v]:
                b = bs[v]
                groups[b] = (groups.get(b, 0) + a[v]) % MOD
        if groups:
            if len(groups) * (r-m) <= 64:
                for w in range(m+1, r+1):
                    total = 0
                    for b, val in groups.items():
                        total += val * fact[w-b]
                    dp[w] = (dp[w] - total) % MOD
            else:
                lo = min(groups)
                hi = max(groups)
                cs = ''.join(f'{groups.get(b, 0):024d}' for b in range(hi, lo-1, -1))
                low = m+1-hi
                high = r-lo
                ks = fs[(n-high)*24:(n-low+1)*24]
                product = format(D(cs) * D(ks), 'f')
                for w in range(m+1, r+1):
                    k = w-m-1+hi-lo
                    end = len(product)-24*k
                    start = max(0, end-24)
                    val = int(product[start:end]) if end > 0 else 0
                    dp[w] = (dp[w] - val) % MOD
        rec(m+1, r)
    rec(1, n)
    return a[n]

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    print(solve(n, data[1].decode()))

if __name__ == '__main__':
    main()

