class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            v = min(right - k, z[k - left]) if k < right else 0
            while k + v < n and nums[v] == nums[k + v]:
                v += 1
            z[k] = v
            if k + v > right:
                left, right = k, k + v

        answer = 0
        for i in range(1, n - 1):
            first_prefix = z[i] >= i
            if first_prefix:
                answer += max(0, n - 2 * i)
            limit = (n - i) // 2
            if first_prefix:
                limit = min(limit, i - 1)

            suffix_z = [0] * (limit + 1)
            left = right = 0
            for k in range(1, limit + 1):
                v = min(right - k, suffix_z[k - left]) if k < right else 0
                while i + k + v < n and nums[i + v] == nums[i + k + v]:
                    v += 1
                suffix_z[k] = v
                if k + v > right:
                    left, right = k, k + v
                if v >= k:
                    answer += 1
        return answer

