class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        best = 0
        previous = 0
        for block in s.split('1'):
            if block:
                length = len(block)
                if previous:
                    best = max(best, previous + length)
                previous = length
        return s.count('1') + best

