def brute(s):
    marked = [False] * len(s)
    score = 0
    for i in range(len(s)):
        for j in range(i - 1, -1, -1):
            if not marked[j] and ord(s[j]) + ord(s[i]) == 219:
                marked[i] = marked[j] = True
                score += i - j
                break
    return score

