def brute(points):
    best = -1
    for corners in combinations(points, 4):
        xs = sorted(set(x for x,y in corners))
        ys = sorted(set(y for x,y in corners))
        if len(xs) != 2 or len(ys) != 2:
            continue
        if set(corners) != {(x,y) for x in xs for y in ys}:
            continue
        others = set(points) - set(corners)
        if any(xs[0] <= x <= xs[1] and ys[0] <= y <= ys[1] for x,y in others):
            continue
        best = max(best, (xs[1]-xs[0])*(ys[1]-ys[0]))
    return best

